alter table products drop constraint if exists products_stock_nonnegative, add constraint products_stock_nonnegative check (stock >= 0), drop constraint if exists products_prices_nonnegative, add constraint products_prices_nonnegative check (cost >= 0 and price >= 0);
alter table sale_items drop constraint if exists sale_items_quantity_positive, add constraint sale_items_quantity_positive check (quantity > 0), drop constraint if exists sale_items_prices_nonnegative, add constraint sale_items_prices_nonnegative check (price >= 0 and cost >= 0);
alter table financial_entries drop constraint if exists financial_entries_amount_positive, add constraint financial_entries_amount_positive check (amount > 0);
create index if not exists idx_customers_company on customers(company_id); create index if not exists idx_products_company on products(company_id); create index if not exists idx_sales_company_status_date on sales(company_id, status, sale_date); create index if not exists idx_sale_items_product on sale_items(product_id); create index if not exists idx_stock_company_product on stock_movements(company_id, product_id); create index if not exists idx_finance_company_status_due on financial_entries(company_id, status, due_date); create index if not exists idx_purchases_company_status on purchases(company_id, status); create index if not exists idx_quotes_company_status on quotes(company_id, status); create index if not exists idx_commissions_company_status on commissions(company_id, status);
